WITH unpacked AS (SELECT id, customer_id, created_at, ship_to, attributes, FORALL(items, li -> li.qty <= 5) AS all_small_qty, EXISTS(coupon_codes, c -> c LIKE 'W%') AS has_welcome_code, COALESCE(ship_to.country, 'UNKNOWN') AS country_or_unknown, COALESCE(attributes['utm_source'], 'none') AS utm_source_or_default FROM carts) SELECT DATE_TRUNC('HOUR', created_at) AS hour_window, customer_id, DATE_TRUNC('DAY', created_at) AS activity_day, MIN(created_at) AS first_seen, MIN(created_at) AS first_created_at, (UNIX_TIMESTAMP(MAX(created_at)) - UNIX_TIMESTAMP(MIN(created_at))) / 60 AS span_minutes, MIN(created_at) AS first_seen_2, (UNIX_TIMESTAMP(MAX(created_at)) - UNIX_TIMESTAMP(MIN(created_at))) / 60 AS duration_min, MAX(created_at) AS ended_at, PERCENT_RANK() OVER (PARTITION BY DATE_TRUNC('HOUR', created_at) ORDER BY (UNIX_TIMESTAMP(MAX(created_at)) - UNIX_TIMESTAMP(MIN(created_at))) / 60 DESC) AS duration_min_percent_rank FROM unpacked GROUP BY hour_window, customer_id, activity_day HAVING span_minutes < 1000000 ORDER BY span_minutes
